<template>
  <view class="family-list-page">
    <!-- 顶部操作栏 -->
    <view class="action-bar card">
      <view class="action-title">
        <text class="title-text">家庭档案管理</text>
        <text class="title-count">共 {{ familyList.length }} 个档案</text>
      </view>
      <view class="add-btn">
        <button class="btn btn-primary btn-small" @click="addFamily">
          <text class="btn-icon">+</text>
          <text class="btn-text">新增</text>
        </button>
      </view>
    </view>

    <!-- 家庭档案列表 -->
    <view class="family-list">
      <view
        class="family-item card"
        v-for="item in familyList"
        :key="item.id"
      >
        <view class="family-header">
          <view class="family-info">
            <text class="family-name">{{ item.name }}</text>
            <view class="default-tag" v-if="item.isDefault === 1">
              <text class="tag-text">默认</text>
            </view>
          </view>
          <view class="family-actions">
            <text class="action-text" @click="viewFamilyDetail(item)">详情</text>
            <text class="action-text" @click="editFamily(item)">编辑</text>
            <text class="action-text delete" @click="deleteFamily(item)">删除</text>
          </view>
        </view>
        <view class="family-body">
          <view class="info-row">
            <view class="info-item">
              <text class="info-icon">🏠</text>
              <text class="info-text">{{ item.roomType }} · {{ item.area }}㎡</text>
            </view>
            <view class="info-item">
              <text class="info-icon">👥</text>
              <text class="info-text">{{ item.memberCount }}位成员</text>
            </view>
          </view>
          <view class="info-row">
            <view class="info-item full">
              <text class="info-icon">📍</text>
              <text class="info-text address">{{ item.address }}</text>
            </view>
          </view>
          <view class="info-row tags-row" v-if="item.hasChildren === 1 || item.hasPets === 1">
            <view class="tag-item" v-if="item.hasChildren === 1">
              <text class="tag-icon">👶</text>
              <text class="tag-label">有小孩</text>
            </view>
            <view class="tag-item" v-if="item.hasPets === 1">
              <text class="tag-icon">🐕</text>
              <text class="tag-label">有宠物</text>
            </view>
          </view>
        </view>
        <view class="family-footer" v-if="item.members && item.members.length > 0">
          <view class="members-header">
            <text class="members-title">家庭成员</text>
            <text class="members-action" @click="manageMembers(item)">管理成员</text>
          </view>
          <view class="members-list">
            <view
              class="member-item"
              v-for="member in item.members.slice(0, 4)"
              :key="member.id"
            >
              <view class="member-avatar">
                <text class="avatar-text">{{ member.name.charAt(0) }}</text>
              </view>
              <view class="member-info">
                <text class="member-name">{{ member.name }}</text>
                <text class="member-relation">{{ member.relation }}</text>
              </view>
            </view>
            <view class="member-item more" v-if="item.members.length > 4" @click="viewFamilyDetail(item)">
              <view class="member-avatar">
                <text class="avatar-text">+{{ item.members.length - 4 }}</text>
              </view>
            </view>
          </view>
        </view>
        <view class="family-reminder">
          <view class="reminder-item" @click="toggleReminder(item)">
            <text class="reminder-icon">{{ item.reminderEnabled ? '🔔' : '🔕' }}</text>
            <text class="reminder-text">{{ item.reminderEnabled ? '提醒已开启' : '提醒已关闭' }}</text>
          </view>
        </view>
      </view>
    </view>

    <!-- 空状态 -->
    <view class="empty" v-if="familyList.length === 0">
      <text class="empty-icon">👨‍👩‍👧‍👦</text>
      <text class="empty-text">暂无家庭档案</text>
      <button class="btn btn-primary btn-small" @click="addFamily">新增家庭档案</button>
    </view>
  </view>
</template>

<script>
import { familyList } from '@/common/data/mockData.js';

export default {
  data() {
    return {
      familyList: []
    };
  },
  onLoad() {
    this.loadData();
  },
  methods: {
    loadData() {
      this.familyList = familyList.map(item => ({
        ...item,
        reminderEnabled: item.id === 1
      }));
    },
    addFamily() {
      uni.showToast({
        title: '新增家庭档案功能',
        icon: 'none'
      });
    },
    viewFamilyDetail(item) {
      uni.showToast({
        title: `查看家庭档案：${item.name}`,
        icon: 'none'
      });
    },
    editFamily(item) {
      uni.showToast({
        title: `编辑家庭档案：${item.name}`,
        icon: 'none'
      });
    },
    deleteFamily(item) {
      uni.showModal({
        title: '删除确认',
        content: `确定删除「${item.name}」的家庭档案吗？删除后无法恢复。`,
        success: (res) => {
          if (res.confirm) {
            const index = this.familyList.findIndex(family => family.id === item.id);
            if (index > -1) {
              this.familyList.splice(index, 1);
            }
            uni.showToast({
              title: '删除成功',
              icon: 'success'
            });
          }
        }
      });
    },
    manageMembers(item) {
      uni.showToast({
        title: `管理「${item.name}」的家庭成员`,
        icon: 'none'
      });
    },
    toggleReminder(item) {
      item.reminderEnabled = !item.reminderEnabled;
      uni.showToast({
        title: item.reminderEnabled ? '提醒已开启' : '提醒已关闭',
        icon: 'none'
      });
    }
  }
};
</script>

<style scoped>
.family-list-page {
  min-height: 100vh;
  background-color: #F8F9FA;
  padding: 30rpx;
}

/* 顶部操作栏 */
.card {
  background-color: #FFFFFF;
  border-radius: 16rpx;
  margin-bottom: 24rpx;
  overflow: hidden;
  box-shadow: 0 2rpx 12rpx rgba(0, 0, 0, 0.05);
}

.action-bar {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24rpx 30rpx;
}

.action-title {
  display: flex;
  flex-direction: column;
}

.title-text {
  font-size: 32rpx;
  font-weight: 600;
  color: #333333;
}

.title-count {
  font-size: 24rpx;
  color: #999999;
  margin-top: 6rpx;
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 12rpx 24rpx;
  border-radius: 20rpx;
  font-size: 24rpx;
  font-weight: 500;
  border: none;
}

.btn-primary {
  background-color: #4CAF50;
  color: #FFFFFF;
}

.btn-small {
  padding: 12rpx 24rpx;
  font-size: 24rpx;
}

.btn-icon {
  font-size: 28rpx;
  margin-right: 6rpx;
}

/* 家庭档案列表 */
.family-list {
  display: flex;
  flex-direction: column;
}

.family-item {
  margin-bottom: 24rpx;
}

.family-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 24rpx 30rpx;
  border-bottom: 1rpx solid #E0E0E0;
}

.family-info {
  display: flex;
  align-items: center;
}

.family-name {
  font-size: 30rpx;
  font-weight: 600;
  color: #333333;
}

.default-tag {
  background-color: #E8F5E9;
  padding: 4rpx 16rpx;
  border-radius: 12rpx;
  margin-left: 12rpx;
}

.tag-text {
  font-size: 20rpx;
  color: #4CAF50;
}

.family-actions {
  display: flex;
}

.action-text {
  font-size: 24rpx;
  color: #4CAF50;
  padding: 8rpx 16rpx;
  margin-left: 16rpx;
}

.action-text.delete {
  color: #F44336;
}

.family-body {
  padding: 20rpx 30rpx;
}

.info-row {
  display: flex;
  margin-bottom: 16rpx;
}

.info-row:last-child {
  margin-bottom: 0;
}

.info-item {
  display: flex;
