  margin-right: 40rpx;
}

.info-item.full {
  flex: 1;
  margin-right: 0;
}

.info-icon {
  font-size: 28rpx;
  margin-right: 8rpx;
}

.info-text {
  font-size: 26rpx;
  color: #666666;
}

.info-text.address {
  flex: 1;
}

.tags-row {
  margin-top: 12rpx;
}

.tag-item {
  display: flex;
  align-items: center;
  background-color: #F5F5F5;
  padding: 8rpx 16rpx;
  border-radius: 20rpx;
  margin-right: 16rpx;
}

.tag-icon {
  font-size: 24rpx;
  margin-right: 6rpx;
}

.tag-label {
  font-size: 22rpx;
  color: #666666;
}

.family-footer {
  padding: 20rpx 30rpx;
  background-color: #FAFAFA;
  border-top: 1rpx solid #E0E0E0;
}

.members-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 16rpx;
}

.members-title {
  font-size: 26rpx;
  font-weight: 500;
  color: #333333;
}

.members-action {
  font-size: 24rpx;
  color: #4CAF50;
}

.members-list {
  display: flex;
  flex-wrap: wrap;
}

.member-item {
  display: flex;
  align-items: center;
  width: 50%;
  padding: 12rpx 0;
}

.member-item.more {
  width: auto;
}

.member-avatar {
  width: 64rpx;
  height: 64rpx;
  background-color: #E8F5E9;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  margin-right: 12rpx;
}

.avatar-text {
  font-size: 28rpx;
  color: #4CAF50;
  font-weight: 500;
}

.member-info {
  display: flex;
  flex-direction: column;
}

.member-name {
  font-size: 26rpx;
