}

.reminder-icon {
  font-size: 28rpx;
  margin-right: 8rpx;
}

.reminder-text {
  font-size: 24rpx;
  color: #666666;
}

/* 空状态 */
.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 100rpx 0;
}

.empty-icon {
  font-size: 120rpx;
  color: #999999;
  margin-bottom: 24rpx;
}

.empty-text {
  font-size: 28rpx;
  color: #999999;
  margin-bottom: 30rpx;
}
</style>
